@Override public int getInt(String propertyName, int defaultValue){
  try {
    Object value = this.getProperty(propertyName);
    if (value == null) {
      return defaultValue;
    }
    return Integer.parseInt(value.toString());
  } catch (NumberFormatException | RuntimeException e) {
    // Log the exception or handle it as needed
    return defaultValue;
  }
}
